with unpacked as (select id, service, level, latency_ms, status_code, context, context['region'] as region, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, coalesce(context['trace'], 'none') as trace_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs where level in ('DEBUG', 'WARN')) select id, service, level, status_code, region, retry_count, duration_sec, round(status_code / sum(status_code) over (partition by level, service), 4) as status_code_share, round(status_code / sum(status_code) over (partition by level), 4) as status_code_share_2 from unpacked where duration_sec is not null;
